@import "tailwindcss";

/* Applies when the person picks "Extra large" text in Settings. */
@custom-variant xl-text (&:where([data-text-size="xlarge"] *));

/*
 * Design tokens from apps/web/DESIGN.md.
 * Contrast rules: coral is a fill only (route, pins, CTA background) — never text,
 * never white-on-coral. Coral buttons use `ink` text. Coral-flavored text uses `rust`.
 * Every 3D view sits on `night`.
 */
@theme {
  --color-paper: #f3ebd0;
  --color-surface: #faf5e6;
  --color-forest: #2f4a3a;
  --color-coral: #f48057;
  --color-rust: #a8421f;
  --color-night: #121c16;
  --color-sage: #a9c4ae;
  --color-ink: #15221b;
  --color-muted: #5e6b60;

  --font-display: "Overpass", ui-sans-serif, system-ui, sans-serif;
  --font-sans: "Atkinson Hyperlegible Next", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Atkinson Hyperlegible Mono", ui-monospace, "SFMono-Regular", monospace;
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
  }

  body {
    @apply bg-paper font-sans text-forest antialiased;
  }

  /*
   * Focus ring for keyboard users. It must reach 3:1 against what's behind it, and
   * coral on cream is only 2.2:1, so the color follows the surface:
   * forest on paper (8.1:1), paper on the forest menu (8.1:1), coral on night (6.7:1).
   */
  :root {
    --focus-ring: var(--color-forest);
  }
  [data-surface="forest"] {
    --focus-ring: var(--color-paper);
  }
  [data-surface="night"] {
    --focus-ring: var(--color-coral);
  }
  [data-surface="light"] {
    --focus-ring: var(--color-forest);
  }

  :focus-visible {
    outline: 3px solid var(--focus-ring);
    outline-offset: 2px;
  }
}

