/* Creators: cards that turn over. Hover with a mouse, tap on a phone, or keyboard focus inside. */
.flip-card {
  perspective: 1100px;
}
.flip-inner {
  transform-style: preserve-3d;
  transition: transform 0.7s cubic-bezier(0.2, 0.8, 0.2, 1);
}
@media (hover: hover) {
  .flip-card:hover .flip-inner {
    transform: rotateY(180deg);
  }
}
.flip-card:focus-within .flip-inner,
.flip-card[data-flipped="true"] .flip-inner {
  transform: rotateY(180deg);
}
.flip-face {
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}
.flip-back {
  transform: rotateY(180deg);
}

/* Join us: footprints step across on a loop. Each print lights up in turn, then fades behind the walker. */
.print-step {
  opacity: 0;
  animation-name: print-step;
  animation-timing-function: ease-out;
  animation-iteration-count: infinite;
  animation-fill-mode: both;
}
@keyframes print-step {
  0% {
    opacity: 0;
  }
  2% {
    opacity: 0.55;
  }
  18% {
    opacity: 0.4;
  }
  40% {
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}

.cursor-print {
  animation: cursor-print 1.8s ease-out forwards;
}
@keyframes cursor-print {
  0% {
    opacity: 0;
  }
  6% {
    opacity: 0.5;
  }
  45% {
    opacity: 0.35;
  }
  100% {
    opacity: 0;
  }
}

/* "Who it's for": sign figures walk (or roll) their route. */
.pg-walker {
  animation: pg-across 2.6s cubic-bezier(0.45, 0.05, 0.4, 1) forwards;
}
.pg-walking .pg-swing {
  transform-box: fill-box;
  transform-origin: 50% 0;
  animation: pg-swing 0.32s ease-in-out 8 alternate;
  animation-delay: var(--pg-delay, 0s);
}
.pg-walking .pg-swing-alt {
  animation-direction: alternate-reverse;
}
.pg-rolling .pg-wheel {
  transform-box: fill-box;
  transform-origin: center;
  animation: pg-spin 2.6s cubic-bezier(0.45, 0.05, 0.4, 1) forwards;
}
@keyframes pg-across {
  to {
    transform: translateX(var(--walk, 218px));
  }
}
@keyframes pg-swing {
  from {
    transform: rotate(22deg);
  }
  to {
    transform: rotate(-22deg);
  }
}
@keyframes pg-spin {
  to {
    transform: rotate(570deg);
  }
}
@keyframes tour-scan {
  to {
    transform: translateY(78px);
  }
}
@keyframes tour-dash {
  to {
    stroke-dashoffset: -6;
  }
}

/*
 * Reduced motion: on when the person picks "Reduce motion" in Settings, or when they
 * keep "Match my device" and the device asks for it. "Allow motion" overrides the device.
 */
@media (prefers-reduced-motion: reduce) {
  :root:not([data-motion="full"]) *,
  :root:not([data-motion="full"]) *::before,
  :root:not([data-motion="full"]) *::after {
    animation-duration: 0.01ms !important;
    animation-delay: 0s !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

