@keyframes hero-twinkle {
  from {
    opacity: 0.15;
  }
  to {
    opacity: 0.8;
  }
}

/* "The problem" loop. Each scene's end state is its finished picture, so reduced motion shows that. */
.pb-progress-x {
  width: 0;
  animation-name: pb-progress-x;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}
.pb-gps {
  transform: translate(60px, 300px);
  animation:
    pb-gps-move 2s ease-in-out forwards,
    pb-gps-drift 1.6s ease-in-out 2.1s infinite alternate;
}
.pb-accuracy,
.pb-pop-svg,
.pb-flash {
  transform-box: fill-box;
  transform-origin: center;
}
.pb-accuracy {
  animation: pb-grow 0.8s ease-out both;
}
.pb-pop,
.pb-pop-svg {
  animation: pb-pop 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.3) both;
}
.pb-rise {
  animation: pb-rise 0.5s ease-out both;
}
.pb-rise.pb-shake {
  animation:
    pb-rise 0.5s ease-out both,
    pb-shake 0.5s ease-in-out both;
}
.pb-zoom {
  animation: pb-zoom 2.4s ease-in-out 0.5s both;
}
.pb-draw {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: pb-draw 1.4s ease-in-out both;
}
.pb-flash {
  animation: pb-flash 0.9s ease-out 3 both;
}
.pb-assemble {
  animation: pb-fade 0.9s ease-out both;
}
@keyframes pb-progress-x {
  to {
    width: 100%;
  }
}
@keyframes pb-gps-move {
  0% {
    transform: translate(60px, 300px);
  }
  25% {
    transform: translate(60px, 220px);
  }
  75% {
    transform: translate(220px, 220px);
  }
  100% {
    transform: translate(220px, 150px);
  }
}
@keyframes pb-gps-drift {
  0% {
    transform: translate(220px, 150px);
  }
  33% {
    transform: translate(196px, 104px);
  }
  66% {
    transform: translate(246px, 92px);
  }
  100% {
    transform: translate(214px, 124px);
  }
}
@keyframes pb-grow {
  from {
    opacity: 0;
    transform: scale(0.3);
  }
}
@keyframes pb-pop {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.9);
  }
}
@keyframes pb-rise {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
}
@keyframes pb-shake {
  0%,
  100% {
    transform: translateX(0);
  }
  20% {
    transform: translateX(-6px);
  }
  40% {
    transform: translateX(6px);
  }
  60% {
    transform: translateX(-4px);
  }
  80% {
    transform: translateX(4px);
  }
}
@keyframes pb-zoom {
  to {
    transform: scale(1.9);
  }
}
@keyframes pb-draw {
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes pb-flash {
  from {
    opacity: 0;
    transform: scale(0.6);
  }
  50% {
    opacity: 1;
  }
