        const message =
          ScanParseError && error instanceof ScanParseError ? error.message : "Unexpected error while reading the scan.";
        setState({ phase: "parse-failed", meta, message });
      }
    })();

    return () => {
      controller.abort();
      geometry?.dispose();
    };
  }, [shareId, attempt]);

